const assert=require('node:assert/strict'),fs=require('node:fs');const {palette,luminance}=require('../../paper-branding.js');for(const value of ['#1d68f0','#ffbb00','#00aa55','#8800aa','#ffffff','#000000','invalid']){const p=palette(value);assert.equal(p['--paper-brand'],/^#[0-9a-f]{6}$/.test(value)?value:'#1d68f0');for(const token of ['--paper-blue','--paper-hero-start','--paper-hero-end'])assert(1.05/(luminance(p[token])+.05)>=4.5,token+' contrast '+value);assert(/^#[0-9a-f]{6}$/.test(p['--paper-tint']));}for(const file of ['paper.html','paper-workspace.html'])assert(fs.readFileSync(file,'utf8').includes('paper-branding.js'));assert(fs.readFileSync('index.html','utf8').includes('UROVIA PAPER</button>'));console.log('PAPER school palette and text contrast OK');